from pathlib import Path
import json,hashlib,datetime,shutil
A=Path(__file__).parent;R=A.parent
def load(p):return json.loads(p.read_text(encoding='utf-8'))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def write(p,x):p.write_text(json.dumps(x,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
f=load(R/'package-freeze.json');assert sha(R/'package-freeze.json')=='18e1e1e2c220c108f74e079043bad72a44551f798be9fb28ded314b49e1622c6'
checks=load(A/'mechanical-checks-v1.json');assert all(x['passed'] for x in checks['checks'])
S=A/'author-v1-read-snapshot';S.mkdir(exist_ok=True)
for name in ['package-freeze.json','source-facts.json','source-inventory.json','source-tables.json','page-coverage.json','original-assets-manifest.json','extraction-notes.md']:
 p=R/name;t=S/name
 if t.exists():assert sha(t)==sha(p)
 else:shutil.copy2(p,t)
findings=[
 {'id':'SOMMER-SOURCE-01','status':'open','scope':'fact sommer2020-insitu-nobase','source':'main p4, In Situ Synthesis','finding':'Low crystallinity is not stated; the paper reports low yield and refinement difficulty.','required_change':'Remove low crystallinity; preserve low yield, source sample limits and values.'},
 {'id':'SOMMER-SOURCE-02','status':'open','scope':'stock insitu-base-solutions','source':'main p8, In Situ XRD: Zn(NO3)2 Based Solutions','finding':'The stock quantities incorrectly include nitrate-stock aliquot and final mixed-reaction Zn/Al concentrations.','required_change':'Retain the NaOH aliquot in this stock; preserve other quantities in the existing mixture fact/operation, with an explicit scope/context link.'},
 {'id':'SOMMER-SOURCE-03','status':'open','scope':'precise locator metadata for sommer2020-d4-solution, sommer2020-d2-size, sommer2020-mw-middle-outcome and mirrored evidence','source':'main pp2,3,5','finding':'Three labels name nearby but incorrect figures although PDF pages are correct.','required_change':'D4 concentration: p2 Al-only precursor paragraph. D2 dimensions: p3 discussion below Figure4. M2 peaks: p5 Figure9 and Laboratory Synthesis. Propagate mirrored labels without source value changes.'},
 {'id':'SOMMER-SOURCE-04','status':'open','scope':'cited-context information coverage','source':'main p3, paragraph below Figure4, reference42','finding':'Cited ZnO formation on heating aqueous zinc nitrate/NaOH at 150–350 degC is present in local full payload but lacks a typed cited-context range.','required_change':'Add separately scoped cited-context range linked to reference42; it is not a current D2 synthesis temperature or independently reviewed cited-paper recipe.'},
 {'id':'SOMMER-SOURCE-05','status':'open','scope':'common laboratory workup inputs/semantics','source':'main p7, Experimental Methods: Laboratory Syntheses','finding':'The common-workup inputs list multiple route crude products; those denote separate specimens, not a pooled batch.','required_change':'Explicitly qualify MW/SCF/ACS specimens as alternatives treated independently. Do not change values or invent a mixing operation.'}
]
bound={str(R/'package-freeze.json'):sha(R/'package-freeze.json')}
bound.update(f['bound_files']);bound.update(f['source_hashes'])
for p in [A/'reading-inputs.json',A/'independent-reading-checkpoint.json',A/'independent-reading-notes.md',A/'independent-table1.json',A/'mechanical-checks-v1.json',A/'check_extraction.py',Path(__file__)]:bound[str(p)]=sha(p)
for p in S.iterdir():bound[str(p)]=sha(p)
report={'schema':'mattersyn-independent-source-audit/1','paper_id':'sommer2020','doi':'10.1021/acs.cgd.9b01519','reviewer':'/root/norberg2004_extract','source_author':'/root/backlog_eta','created_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'status':'open_findings','audited_source_revision':1,'source_freeze_sha256':sha(R/'package-freeze.json'),'independent_reading_preceded_author_comparison':True,'manual_scope':{'main_pages_read_and_visually_viewed':list(range(1,12)),'si_pages_read':0,'selected_original_crops_viewed':20,'facts':64,'fact_quantities':136,'table_rows':37,'table_data_cells':185,'table_label_cells':37,'protocols':12,'operations':31,'materials':28,'stocks':7,'sample_contexts':44,'figures_including_graphical_abstract':14,'expressions':7,'references_read_as_printed_citations':65,'references_full_text_reviewed':0,'source_conflicts_preserved':13,'missingness_categories':7,'inventory_units':331},'method':'Independently read all eleven original text pages and original independently rendered page images before opening author facts; froze a manual Table1 transcription, then compared every author scientific item and all twenty selected crops. Independently replayed all crops from the retained PDF and resolved every table token and inventory pointer. Mechanical counts supplement this manual source reading and are not a proxy for it.','independent_mechanical_checks':len(checks['checks']),'findings':findings,'limits':['Main-only source audit. SI is declared but locally unlocated/unverified.','No exact measured coordinate pair, complete synthesis execution, canonical, molecular/apparatus, mounted browser, training, Site integration or publication approval.','C1–C13 are unresolved printed-source discrepancies and remain preserved; no silent normalization.'],'bound_files':bound}
write(A/'independent-audit-v1.json',report)
(A/'independent-audit-v1.md').write_text('# Independent Sommer source audit — revision 1\n\nStatus: open findings. Reviewer `/root/norberg2004_extract`; author `/root/backlog_eta`.\n\nAll 11 supplied main pages and 20 selected crops were actually read/viewed, including all 64 facts/136 quantities and all 222 Table 1 body cells. The independent pre-author reading checkpoint and table transcription are retained. '+str(len(checks['checks']))+' independent mechanical checks passed.\n\n'+'\n'.join('- **'+x['id']+'**: '+x['finding']+' '+x['required_change'] for x in findings)+'\n\nSI remains locally unlocated/unverified. Printed source conflicts C1–C13 remain explicit. No downstream canonical, visual, training or publication gate is approved here.\n\nFrozen source SHA256: `'+report['source_freeze_sha256']+'`. Exact input hashes are recorded in the JSON.\n',encoding='utf-8')
print(json.dumps({'report':str(A/'independent-audit-v1.json'),'sha256':sha(A/'independent-audit-v1.json'),'checks':len(checks['checks']),'bound_files':len(bound),'findings':len(findings)}))
